box 1800 15000 -5700 -5680 1800 000000 hidden collision role=air_gate_right
floor -12000 -1800 -5900 -5700 26394A
floor 1800 12000 -5900 -5700 26394A
label -14000 14000 -6200 -6000 70D8FF AIR WALL CONTROL LINE

